    B = (uint8_t)(B >> 1);                           /* LB26A */
    B &= 0x0F;                                       /* LB26B  PANEL EVERY 800(16 PANELS DEEP) */
    X = (uint16_t)(X + B);                           /* LB26D  POINT INTO PANEL FLAG RAM */
    D = rd16(LZ_PNX);                                /* LB26E */
    A &= 0x07;                                       /* LB270 */
    D = sub16(D, (0x200-LZR));                       /* LB272 */
    CYC(29);
