/* LZHPN ($B29C) - J HIT A PANEL
 * Condition codes in: C; out: C.
 */
void lzhpn(void)
{
    CK(0xB29C);
    A = M8(TMPMSK);                                  /* LB29C */
    A &= rd8(X);                                     /* LB29E  CHECK FOR TYPE OF PANEL */
    CYC(11);
    if (A != 0) {                                    /* LB2A0  IFNE  ?ALIVE? */
        M8(TMPFLG) = A;                              /* LB2A2  SAVEIT, IS 1,2,3 IN THE SLOT */
        A = M8(TMPMSK);                              /* LB2A4 */
        A = (uint8_t)(A << 1);                       /* LB2A6 */
        A &= M8(TMPMSK);                             /* LB2A7  GEN A TYPE 2 IN CORRECT SLOT */
        cmp8(A, M8(TMPFLG));                         /* LB2A9  CHECK AGAINST MASKED PANEL TYPE */
        CYC(21);
        if (!CCZ) {                                  /* LB2AB  IFNE  ?NOT A FORCE FIELD? */
            CYC(3);
            if (!(CCC | CCZ)) {                      /* LB2AD  IFHI  MUST HAVE BEEN A 1, I.E. A DECORATIVE PANEL */
                A = 0x04;                            /* LB2AF  STICK HERE AND SHOW A HIT */
                M8(LZ_HIT) = A;                      /* LB2B1 */
                A = rd8(X);                          /* LB2B3 */
                A ^= M8(TMPFLG);                     /* LB2B5  GET RID OF PANEL */
                wr8(X, A);                           /* LB2B7  STORED BACK */
                CYC(26);
                JSR(scrpnl);                         /* LB2B9  SCORE FOR A PANEL */
                CYC(8);
                JSR(audsx);                          /* LB2BC */
                CYC(3);
            } else {                                 /* LB2BF  ELSE  MUST BE A TURRET */
                A = 0x04;                            /* LB2C1  STICK HERE AND SHOW A HIT */
                M8(LZ_HIT) = A;                      /* LB2C3 */
                A = rd8(X);                          /* LB2C5 */
                A ^= M8(TMPFLG);                     /* LB2C7  GET RID OF PANEL */
                wr8(X, A);                           /* LB2C9  STORED BACK */
                CYC(26);
                JSR(scrtrt);                         /* LB2CB  KILLED A TURRET */
                CYC(8);
                JSR(audsx);                          /* LB2CE */
            }
        }
    }
    CYC(5);
    RTS;                                             /* LB2D1 */
}

